#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

bool isVowel(char c) {
    return c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U';
}

int main() {
    string s;
    cin >> s;

    int answer = 0;
    int last = -1;

    for (int i = 0; i <= static_cast<int>(s.size()); ++i) {
        if (i == static_cast<int>(s.size()) || isVowel(s[i])) {
            answer = max(answer, i - last);
            last = i;
        }
    }

    cout << answer;
    return 0;
}

#include <iostream>
