#include <algorithm>
using namespace std;

bool pd(char x) {
    return x == 'A' || x == 'E' || x == 'I' || x == 'O' || x == 'U';
}

int main() {
    string s;
    cin >> s;

    int ans = 1;
    int current = 1;

    for (char c : s) {
        if (pd(c)) {
            ans = max(ans, current);
            current = 1;
        } else {
            ++current;
        }
    }

    ans = max(ans, current);
    cout << ans;
    return 0;
}

#include <iostream>
