#include <string>
#include <vector>
using namespace std;

bool pd(char x) {
    return x == 'A' || x == 'E' || x == 'I' || x == 'O' || x == 'U';
}

int main() {
    string s;
    cin >> s;

    int ans = 1;
    vector<int> a;

    for (size_t i = 1; i <= s.size(); ++i) {
        if (i < s.size() && pd(s[i])) {
            a.push_back(ans);
            ans = 0;
        } else {
            ++ans;
        }
    }

    if (a.empty()) {
        cout << ans;
    } else {
        sort(a.begin(), a.end());
        cout << a.back() + 1;
    }

    return 0;
}

